1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <meta name="description" content="An accessible, animated pulsing circle with adjustable speed and pause controls.">
7	  <meta name="color-scheme" content="dark">
8	  <meta name="theme-color" content="#0d0d17">
9	  <title>Pulsing Circle</title>
10	  <style>
11	    :root {
12	      --circle-hue: #8ec5ff;
13	      --circle-core: #4a7dd9;
14	      --circle-shadow: #1f3a75;
15	      --cycle: 2.5s;
16	    }
17	    * {
18	      margin: 0;
19	      padding: 0;
20	      box-sizing: border-box;
21	    }
22	    body {
23	      width: 100vw;
24	      height: 100vh;
25	      height: 100dvh;
26	      display: flex;
27	      flex-direction: column;
28	      justify-content: center;
29	      align-items: center;
30	      gap: 24px;
31	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
32	      overflow: hidden;
33	    }
34	    svg {
35	      width: min(400px, 80vmin);
36	      height: min(400px, 80vmin);
37	      overflow: visible;
38	      cursor: pointer;
39	      user-select: none;
40	      -webkit-tap-highlight-color: transparent;
41	      transition: filter 0.3s ease;
42	    }
43	    .circle-btn:hover svg {
44	      filter: brightness(1.08);
45	    }
46	    .ambient {
47	      fill: var(--circle-hue);
48	      opacity: 0.12;
49	      filter: blur(30px);
50	      animation: breathe var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
51	      transform-origin: 200px 200px;
52	      will-change: transform, opacity;
53	    }
54	    .core {
55	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
56	      transform-origin: 200px 200px;
57	      filter: url(#glow);
58	      will-change: transform, opacity;
59	    }
60	    .highlight {
61	      fill: url(#highlightGradient);
62	      transform-origin: 200px 200px;
63	      animation: pulse var(--cycle) cubic-bezier(0.4, 0, 0.2, 1) infinite;
64	      pointer-events: none;
65	      will-change: transform, opacity;
66	    }
67	    .ring {
68	      fill: none;
69	      stroke: var(--circle-hue);
70	      stroke-width: 2.5;
71	      transform-origin: 200px 200px;
72	      animation: ripple var(--cycle) cubic-bezier(0.2, 0.6, 0.4, 1) infinite;
73	      will-change: transform, opacity, stroke-width;
74	    }
75	    .ring--delay-1 {
76	      animation-delay: calc(var(--cycle) / 3);
77	    }
78	    .ring--delay-2 {
79	      animation-delay: calc(var(--cycle) / 3 * 2);
80	    }
81	    @keyframes pulse {
82	      0%, 100% {
83	        transform: scale(1);
84	        opacity: 0.9;
85	      }
86	      50% {
87	        transform: scale(1.05);
88	        opacity: 1;
89	      }
90	    }
91	    @keyframes breathe {
92	      0%, 100% {
93	        transform: scale(0.95);
94	        opacity: 0.1;
95	      }
96	      50% {
97	        transform: scale(1.1);
98	        opacity: 0.18;
99	      }
100	    }
101	    @keyframes ripple {
102	      0% {
103	        transform: scale(1);
104	        opacity: 0.6;
105	        stroke-width: 2.5;
106	      }
107	      100% {
108	        transform: scale(1.35);
109	        opacity: 0;
110	        stroke-width: 0.5;
111	      }
112	    }
113	    body.paused .core,
114	    body.paused .ring,
115	    body.paused .ambient,
116	    body.paused .highlight {
117	      animation-play-state: paused;
118	    }
119	    @media (prefers-reduced-motion: reduce) {
120	      /* Avoid a flash of motion before JS applies the paused state. */
121	      .core,
122	      .ring,
123	      .ambient,
124	      .highlight {
125	        animation-play-state: paused;
126	      }
127	    }
128	    .speed-label {
129	      color: var(--circle-hue);
130	      font-family: system-ui, sans-serif;
131	      font-size: 0.85rem;
132	      letter-spacing: 0.05em;
133	      opacity: 0.85;
134	      user-select: none;
135	      text-align: center;
136	    }
137	    .hint {
138	      display: block;
139	      margin-top: 4px;
140	      font-size: 0.7rem;
141	      opacity: 0.85;
142	    }
143	    .controls {
144	      display: flex;
145	      align-items: center;
146	      gap: 12px;
147	      max-width: min(320px, 90vw);
148	    }
149	    .pause-btn {
150	      display: inline-flex;
151	      align-items: center;
152	      justify-content: center;
153	      width: 36px;
154	      height: 36px;
155	      padding: 0;
156	      border-radius: 50%;
157	      border: 1px solid var(--circle-hue);
158	      background: transparent;
159	      color: var(--circle-hue);
160	      cursor: pointer;
161	      transition: background 0.2s ease;
162	    }
163	    .pause-btn:hover {
164	      background: rgba(142, 197, 255, 0.15);
165	    }
166	    .pause-btn:focus-visible {
167	      outline: 2px solid var(--circle-hue);
168	      outline-offset: 2px;
169	    }
170	    @media (prefers-contrast: more) {
171	      .pause-btn {
172	        border-width: 2px;
173	      }
174	      .ring {
175	        stroke-width: 3.5;
176	      }
177	    }
178	    .pause-btn svg {
179	      width: 14px;
180	      height: 14px;
181	    }
182	    .circle-btn {
183	      display: inline-flex;
184	      padding: 0;
185	      border: none;
186	      background: none;
187	      cursor: pointer;
188	      -webkit-tap-highlight-color: transparent;
189	      border-radius: 50%;
190	    }
191	    .circle-btn:focus-visible svg {
192	      outline: 2px solid var(--circle-hue);
193	      outline-offset: 8px;
194	      border-radius: 50%;
195	    }
196	  </style>
197	</head>
198	<body>
199	  <button type="button" class="circle-btn" id="circleBtn" aria-label="Pulsing blue circle animation. Click to change pulse speed." aria-describedby="speedText">
200	  <svg id="ae683f770" viewBox="0 0 400 400" focusable="false">
201	    <title>Pulsing blue circle animation</title>
202	    <defs>
203	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
204	        <stop offset="0%" stop-color="#8ec5ff"/>
205	        <stop offset="55%" stop-color="#4a7dd9"/>
206	        <stop offset="100%" stop-color="#1f3a75"/>
207	      </radialGradient>
208	      <radialGradient id="highlightGradient" cx="32%" cy="28%" r="22%">
209	        <stop offset="0%" stop-color="#ffffff" stop-opacity="0.55"/>
210	        <stop offset="100%" stop-color="#ffffff" stop-opacity="0"/>
211	      </radialGradient>
212	      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%">
213	        <feGaussianBlur in="SourceGraphic" stdDeviation="10" result="blur"/>
214	        <feColorMatrix in="blur" type="matrix"
215	          values="0 0 0 0 0.55  0 0 0 0 0.77  0 0 0 0 1  0 0 0 0.9 0" result="tintedBlur"/>
216	        <feMerge>
217	          <feMergeNode in="tintedBlur"/>
218	          <feMergeNode in="SourceGraphic"/>
219	        </feMerge>
220	      </filter>
221	    </defs>
222	    <circle class="ambient" cx="200" cy="200" r="160"/>
223	    <circle class="ring" cx="200" cy="200" r="140"/>
224	    <circle class="ring ring--delay-1" cx="200" cy="200" r="140"/>
225	    <circle class="ring ring--delay-2" cx="200" cy="200" r="140"/>
226	    <circle class="core" cx="200" cy="200" r="140" fill="url(#circleGradient)"/>
227	    <circle class="highlight" cx="200" cy="200" r="140"/>
228	  </svg>
229	  </button>
230	  <div class="controls">
231	    <button type="button" class="pause-btn" id="pauseBtn" aria-pressed="false" aria-label="Pause animation">
232	      <svg id="pauseIcon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">
233	        <path d="M6 4h4v16H6zM14 4h4v16h-4z"/>
234	      </svg>
235	    </button>
236	    <p class="speed-label" id="speedLabel">
237	      <span id="speedText" aria-live="polite">Normal speed</span>
238	      <span class="hint" aria-hidden="true">Click circle to change speed</span>
239	    </p>
240	  </div>
241	  <script>
242	    const circleBtn = document.getElementById('circleBtn');
243	    const speedText = document.getElementById('speedText');
244	    const pauseBtn = document.getElementById('pauseBtn');
245	    const pauseIcon = document.getElementById('pauseIcon');
246	    const PLAY_ICON = '<path d="M8 5l11 7-11 7z"/>';
247	    const PAUSE_ICON = '<path d="M6 4h4v16H6zM14 4h4v16h-4z"/>';
248	    const speeds = [
249	      { value: '2.5s', name: 'Normal speed' },
250	      { value: '1.2s', name: 'Fast speed' },
251	      { value: '4.5s', name: 'Slow speed' },
252	    ];
253	    let speedIndex = 0;
254	    const reducedMotionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
255	    let manuallyPaused = reducedMotionQuery.matches;
256	
257	    function updateLabels() {
258	      const { name } = speeds[speedIndex];
259	      speedText.textContent = manuallyPaused ? `${name} (paused)` : name;
260	    }
261	
262	    function cycleSpeed() {
263	      speedIndex = (speedIndex + 1) % speeds.length;
264	      const { value } = speeds[speedIndex];
265	      circleBtn.style.setProperty('--cycle', value);
266	      // Restart animations from the beginning so the new speed feels immediate
267	      // instead of jumping mid-cycle.
268	      document.querySelectorAll('.core, .ring, .ambient, .highlight').forEach((el) => {
269	        el.style.animation = 'none';
270	        void el.offsetWidth;
271	        el.style.animation = '';
272	      });
273	      updateLabels();
274	    }
275	
276	    function applyPauseState() {
277	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
278	      pauseBtn.setAttribute('aria-pressed', String(manuallyPaused));
279	      pauseBtn.setAttribute('aria-label', manuallyPaused ? 'Resume animation' : 'Pause animation');
280	      pauseIcon.innerHTML = manuallyPaused ? PLAY_ICON : PAUSE_ICON;
281	      updateLabels();
282	    }
283	
284	    function togglePause() {
285	      manuallyPaused = !manuallyPaused;
286	      applyPauseState();
287	    }
288	
289	    circleBtn.addEventListener('click', cycleSpeed);
290	    pauseBtn.addEventListener('click', togglePause);
291	
292	    document.addEventListener('visibilitychange', () => {
293	      document.body.classList.toggle('paused', document.hidden || manuallyPaused);
294	    });
295	
296	    reducedMotionQuery.addEventListener('change', (e) => {
297	      manuallyPaused = e.matches;
298	      applyPauseState();
299	    });
300	
301	    applyPauseState();
302	  </script>
303	</body>
304	</html>
