input.new_string:
/* Force-paused until JS takes over (below), avoiding a flash of motion;
   once JS is ready, control defers entirely to body.paused so the user
   can still explicitly resume even with reduced motion preferred. */
@media (prefers-reduced-motion: reduce) {
  body:not(.js-ready) .core,
  body:not(.js-ready) .ring,
  body:not(.js-ready) .ambient,
  body:not(.js-ready) .highlight {
    animation-play-state: paused;
  }
}

